CPU.write_state:
/Function(function (vec) {
            if (typeof vec.CPU == "undefined") {
                vec.CPU = {};
            }
            var internal_reg = ["PC"];
            var value = 0;
            for (var idx in sim_p.states.BR) {
                if (typeof sim_p.states.BR[idx] === "undefined")
                    continue;
                value = get_value(sim_p.states.BR[idx]) >>> 0;
                if (value != 0) {
                    vec.CPU["R" + idx] = {
                        "type": "register",
                        "default_value": 0x0,
                        "id": "R" + idx,
                        "op": "=",
                        "value": "0x" + value.toString(16)
                    };
                }
            }
            for (var i = 0; i < internal_reg.length; i++) {
                value = get_value(sim_p.states['REG_' + internal_reg[i]]) >>> 0;
                if (value != 0) {
                    vec.CPU[internal_reg[i]] = {
                        "type": "register",
                        "default_value": 0x0,
                        "id": internal_reg[i],
                        "op": "=",
                        "value": "0x" + value.toString(16)
                    };
                }
            }
            return vec;
        })/

CPU.read_state:
/Function(function (vec, check) {
            if (typeof vec.CPU == "undefined") {
                vec.CPU = {};
            }
            var key = check["id"].toUpperCase().trim();
            var val = parseInt(check["value"]).toString(16);
            if ("REGISTER" == check["type"].toUpperCase().trim()) {
                vec.CPU[key] = {
                    "type": "register",
                    "default_value": 0,
                    "id": key,
                    "op": check["condition"],
                    "value": "0x" + val
                };
                return true;
            }
            return false;
        })/

CPU.get_state:
/Function(function (reg) {
            var value = 0;
            var r_reg = reg.toUpperCase().trim();
            if (typeof sim_p.states['REG_' + r_reg] != "undefined") {
